function validate([nums, quantity]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each value in nums is an integer from 1 to 1000.';
  if (new Set(nums).size > 50) return 'nums may hold at most 50 distinct values.';
  if (!Array.isArray(quantity) || quantity.length < 1 || quantity.length > 10) return 'quantity needs 1 to 10 orders.';
  if (quantity.some(q => !Number.isInteger(q) || q < 1 || q > 100000)) return 'Each order is an integer from 1 to 100000.';
  return null;
}

