function canDistribute(nums, quantity) {
  const counts = new Map();
  for (const num of nums) {
    counts.set(num, (counts.get(num) || 0) + 1);
  }
  const m = quantity.length;
  const full = (1 << m) - 1;
  const need = new Array(full + 1).fill(0);
  for (let mask = 1; mask <= full; mask++) {
    const low = mask & -mask;
    const bit = 31 - Math.clz32(low);
    need[mask] = need[mask ^ low] + quantity[bit];
  }

  let dp = new Array(full + 1).fill(false);
  dp[0] = true;
  for (const count of counts.values()) {
    const next = dp.slice();
    for (let mask = 0; mask <= full; mask++) {
      if (!dp[mask]) continue;
      const rest = full ^ mask;
      for (let sub = rest; sub > 0; sub = (sub - 1) & rest) {
        if (need[sub] <= count) {
          next[mask | sub] = true;
        }
      }
    }
    dp = next;
  }
  return dp[full];
}

