function canDistribute(nums, quantity) {
  const left = new Map();
  for (const v of nums) left.set(v, (left.get(v) || 0) + 1);
  const values = [...left.keys()];
  const place = (i) => {
    if (i === quantity.length) return true;
    for (const v of values) {
      if (left.get(v) < quantity[i]) continue;
      left.set(v, left.get(v) - quantity[i]);
      const ok = place(i + 1);
      left.set(v, left.get(v) + quantity[i]);
      if (ok) return true;
    }
    return false;
  };
  return place(0);
}

