function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 10);
    const distinct = int(1, 4);
    const nums = Array.from({ length: n }, () => int(1, distinct));
    const quantity = Array.from({ length: int(1, 5) }, () => int(1, 4));
    return [nums, quantity];
  }
  const shuffle = (list) => { for (let i = list.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [list[i], list[j]] = [list[j], list[i]]; } return list; };
  const pool = shuffle(Array.from({ length: 1000 }, (_, i) => i + 1));
  if (rand() < 0.4) {
    // Loose: 2,000 numbers over up to 50 values; the 10 orders are carved from the counts, so the answer is true.
    const k = int(1, 50);
    const counts = new Array(k).fill(0);
    const nums = [];
    for (let i = 0; i < 2000; i++) { const idx = Math.floor(rand() * rand() * k); counts[idx]++; nums.push(pool[idx]); }
    const quantity = [];
    for (let c = 0; c < 10; c++) {
      const open = counts.map((r, i) => r > 0 ? i : -1).filter(i => i >= 0);
      if (!open.length) { quantity.push(1); continue; }
      const idx = open[Math.floor(rand() * open.length)];
      const q = int(1, Math.min(counts[idx], 400));
      counts[idx] -= q;
      quantity.push(q);
    }
    return [nums, quantity];
  }
  // Tight: up to 10 values whose counts are split exactly into the 10 orders; moving one unit between orders usually breaks it.
  const k = int(1, 10);
  const cuts = new Set();
  while (cuts.size < k - 1) cuts.add(int(1, 199) * 10);
  const bounds = [0, ...[...cuts].sort((a, b) => a - b), 2000];
  const counts = bounds.slice(1).map((b, i) => b - bounds[i]);
  const owners = shuffle([...Array.from({ length: k }, (_, i) => i), ...Array.from({ length: 10 - k }, () => int(0, k - 1))]);
  const quantity = [];
  for (let v = 0; v < k; v++) {
    const parts = owners.filter(o => o === v).length;
    const marks = new Set();
    while (marks.size < parts - 1) marks.add(int(1, counts[v] - 1));
    const edges = [0, ...[...marks].sort((a, b) => a - b), counts[v]];
    for (let i = 1; i < edges.length; i++) quantity.push(edges[i] - edges[i - 1]);
  }
  shuffle(quantity);
  if (rand() < 0.6) {
    const from = quantity.findIndex(q => q > 1);
    let to = int(0, 9);
    if (to === from) to = (to + 1) % 10;
    if (from >= 0) { quantity[from]--; quantity[to]++; }
  }
  const nums = shuffle(counts.flatMap((c, v) => new Array(c).fill(pool[v])));
  return [nums, quantity];
}
